questions.solution:
function findCycle(waitsFor) {
  for (const start of Object.keys(waitsFor).map(Number).sort((a, b) => a - b)) {
    const path = [];
    let current = start;
    while (current !== undefined && !path.includes(current)) {
      path.push(current);
      current = waitsFor[current];
    }
    if (current === start) return path;
  }
  return null;
}

console.log(findCycle({ 101: 102, 102: 103, 103: 101, 104: 101 }));
console.log(findCycle({ 201: 202, 202: 203 }));

