const store = new Map([[1, { id: 1, dailyLimitKobo: 10000000, version: 1 }]]);

function save(store, id, changes, expectedVersion) {
  const current = store.get(id);
  if (!current || current.version !== expectedVersion) return "conflict";
  const next = { ...current, ...changes, version: current.version + 1 };
  store.set(id, next);
  return `saved v${next.version}`;
}

console.log(save(store, 1, { dailyLimitKobo: 5000000 }, 1));
console.log(save(store, 1, { dailyLimitKobo: 20000000 }, 1));
