const opening = { 1: 5000000, 2: 1000000, 3: 0 };
const balances = { 1: 2000000, 2: 1500000, 3: 3000000 };
const transfers = [
  { from: 1, to: 2, amountKobo: 3000000 },
  { from: 2, to: 3, amountKobo: 2500000 },
];

function reconcile(opening, balances, transfers) {
  const expected = { ...opening };
  for (const t of transfers) {
    expected[t.from] -= t.amountKobo;
    expected[t.to] += t.amountKobo;
  }
  const broken = Object.keys(balances).map(Number).filter((id) => balances[id] !== expected[id]);
  const sum = (o) => Object.values(o).reduce((a, b) => a + b, 0);
  return { broken, totalUnchanged: sum(balances) === sum(opening) };
}

console.log(reconcile(opening, balances, transfers));

