const adaBalance = [
  { committedAt: 3, value: 5000000 },
  { committedAt: 11, value: 2000000 },
];

function visible(versions, snapshot) {
  let newest;
  for (const version of versions) {
    if (version.committedAt <= snapshot && (!newest || version.committedAt > newest.committedAt)) newest = version;
  }
  return newest?.value;
}

console.log("repeatable read (snapshot 10):", visible(adaBalance, 10));
console.log("read committed, next statement (snapshot 12):", visible(adaBalance, 12));
