function replay(start, steps) {
  let balance = start;
  const seen = {};
  for (const [action, tx, amount] of steps) {
    if (action === "read") seen[tx] = balance;
    else balance = seen[tx] - amount;
  }
  return balance;
}

const serial = [["read", "A"], ["write", "A", 30000], ["read", "B"], ["write", "B", 40000]];
const overlapping = [["read", "A"], ["read", "B"], ["write", "A", 30000], ["write", "B", 40000]];
