const jobs = [
  { id: 1, status: "queued" },
  { id: 2, status: "done" },
  { id: 3, status: "queued" },
  { id: 4, status: "queued" },
];

function claim(jobs, locked) {
  const job = jobs
    .filter((j) => j.status === "queued" && !locked.has(j.id))
    .sort((a, b) => a.id - b.id)[0];
  return job ? job.id : null;
}

const locked = new Set();
const taken = { w1: [], w2: [] };
for (let turn = 0; ; turn++) {
  const worker = turn % 2 === 0 ? "w1" : "w2";
  const id = claim(jobs, locked);
  if (id === null) break;
  locked.add(id);
  taken[worker].push(id);
}
console.log(taken);
